// ============================================================
// 自定义附加参数注入脚本（例如：禁用 DeepSeek 思维链）
// 用法：在 SillyTavern 的“扩展脚本”或“自定义 JavaScript”中粘贴此代码。
// 生效后，所有发往 /api/backends/chat-completions/generate 的请求
// 都会自动添加 { thinking: { type: "disabled" } } 到请求体。
// ============================================================

(function() {
    'use strict';

    // ---------- 配置 ----------
    // 要注入的参数对象（可在此自由修改）
    const EXTRA_PARAMS = {
        thinking: {
            type: "disabled"
        }
    };

    // 是否只对特定模型生效（留空则对所有模型生效）
    const TARGET_MODELS = []; // 例如 ['deepseek-v4-pro', 'deepseek-v4-flash']

    // 是否只对非流式请求生效（false = 对所有请求生效）
    const ONLY_NON_STREAM = false;

    // 是否启用调试日志
    const DEBUG = true;
    // -------------------------

    function log(...args) {
        if (DEBUG) console.log('[ExtraParamsInject]', ...args);
    }

    // 检查请求体是否应该被注入
    function shouldInject(bodyObj) {
        if (!bodyObj || typeof bodyObj !== 'object') return false;

        // 如果指定了目标模型，且请求体中的 model 不在列表中，则跳过
        if (TARGET_MODELS.length > 0) {
            const model = bodyObj.model || '';
            if (!TARGET_MODELS.includes(model)) {
                log(`跳过模型 ${model}，不在目标列表中`);
                return false;
            }
        }

        // 如果只允许非流式，且请求是流式的，则跳过
        if (ONLY_NON_STREAM && bodyObj.stream === true) {
            log('跳过流式请求');
            return false;
        }

        return true;
    }

    // 注入参数到请求体对象（直接修改原对象）
    function injectParams(bodyObj) {
        // 如果已有 thinking 字段，则合并（这里简单覆盖，也可以深度合并）
        // 为了安全，我们只添加不存在的字段，或按需求覆盖
        for (const [key, value] of Object.entries(EXTRA_PARAMS)) {
            if (bodyObj[key] === undefined) {
                bodyObj[key] = value;
                log(`注入字段 ${key}:`, value);
            } else {
                // 如果已存在，可根据需要做深度合并（这里简单记录）
                log(`字段 ${key} 已存在，未覆盖`);
            }
        }
        return bodyObj;
    }

    // 劫持 fetch
    const originalFetch = window.fetch;

    window.fetch = function(input, init) {
        // 只处理 POST 请求到 generate 端点
        const url = typeof input === 'string' ? input : input?.url || '';
        if (!url.includes('/api/backends/chat-completions/generate')) {
            return originalFetch.call(this, input, init);
        }

        const method = init?.method || input?.method || 'GET';
        if (method.toUpperCase() !== 'POST') {
            return originalFetch.call(this, input, init);
        }

        // 读取请求体
        let bodyText = init?.body;
        if (!bodyText && input && typeof input === 'object' && input.body) {
            bodyText = input.body;
        }

        // 如果 body 是 FormData 或其它类型，可能无法直接解析，我们只处理 JSON 字符串
        if (typeof bodyText !== 'string') {
            log('请求体不是字符串，跳过');
            return originalFetch.call(this, input, init);
        }

        try {
            const bodyObj = JSON.parse(bodyText);
            if (!shouldInject(bodyObj)) {
                // 不需要注入，直接转发
                return originalFetch.call(this, input, init);
            }

            // 注入参数
            injectParams(bodyObj);

            // 重建请求
            const newBody = JSON.stringify(bodyObj);

            // 如果 init 存在，则修改 init.body，否则修改 input 的 body（需处理 Request 对象）
            if (init) {
                // 如果是 Request 对象，需要构建新的 Request
                if (typeof input === 'object' && input.url) {
                    // input 是 Request 对象，不能直接修改，需要构造新 Request
                    const newInit = { ...init, body: newBody };
                    const newRequest = new Request(input.url, newInit);
                    return originalFetch.call(this, newRequest, newInit);
                } else {
                    // 普通 fetch(url, init) 形式
                    const newInit = { ...init, body: newBody };
                    return originalFetch.call(this, input, newInit);
                }
            } else {
                // 只有 url 没有 init 的情况（很少见）
                const newInit = { method: 'POST', body: newBody };
                return originalFetch.call(this, input, newInit);
            }
        } catch (e) {
            log('解析/注入失败:', e);
            // 出错时仍放行原始请求
            return originalFetch.call(this, input, init);
        }
    };

    log('附加参数注入脚本已启动');
    log('注入内容:', EXTRA_PARAMS);
})();
